#!/usr/bin/env bash
# File length ceiling (AGENTS.md: aim for ~200 lines, 300 max). Split along a real interface.
set -euo pipefail
MAX="${MAX_LINES:-300}"
fail=0
for f in "$@"; do
  [ -f "$f" ] || continue
  # Generated data ("/* GENERATED by ...") is rebuilt by its script; a data table
  # ("/* TABLE: ...", e.g. translations) is one entry per item, so splitting it would be arbitrary.
  head -1 "$f" | grep -qE '^/\* (GENERATED|TABLE:)' && continue
  n=$(wc -l <"$f")
  if [ "$n" -gt "$MAX" ]; then
    echo "check-size: $f has $n lines (max $MAX). Split it along a real interface." >&2
    fail=1
  fi
done
exit "$fail"
